export interface OptionContract {
  strike: number;
  bid: number | null;
  ask: number | null;
  last: number | null;
  vol: number | null;
  oi: number | null;
  delta: number | null;
  theta: number | null;
}

export interface ExpirationDate {
  date: string; // ISO date string YYYY-MM-DD
  daysToExpiration: number;
  strikes: OptionContract[];
}

export interface MarketData {
  ticker: string;
  currentPrice: number;
  lastUpdated: number;
  chain: ExpirationDate[];
}

export interface TradeInputs {
  ticker: string;
  targetAPY: number; // Percentage, e.g., 15
  targetDiscount: number; // Percentage, e.g., 10
  selectedDate: string | null; // Selected expiration date
}

export interface TradeCalculation {
  calculatedStrike: number;
  collateral: number;
  dte: number;
  requiredTotalCredit: number;
  actualTotalCredit: number; // Based on market data bid
  actualAPY: number;
  netPurchasePrice: number;
  isTargetMet: boolean;
  actualPremiumPerShare: number;
  option: OptionContract;
}

import { MarketData, ExpirationDate, OptionContract } from '../types';
import { API_KEY } from '../constants';

type MarketCallback = (data: MarketData) => void;
type LogCallback = (message: string) => void;

export class MarketDataService {
  private subscribers: Map<string, Set<MarketCallback>> = new Map();
  private logSubscribers: Set<LogCallback> = new Set();
  private currentTicker: string | null = null;

  private pollingInterval: number | null = null;
  private lastMarketData: MarketData | null = null;

  constructor() {}

  public subscribeLogs(callback: LogCallback): () => void {
    this.logSubscribers.add(callback);
    return () => this.logSubscribers.delete(callback);
  }

  private log(msg: string) {
    const timestamp = new Date().toLocaleTimeString();
    const formattedMsg = `[${timestamp}] ${msg}`;
    console.log(formattedMsg);
    this.logSubscribers.forEach(cb => cb(formattedMsg));
  }

  private error(msg: string, err?: any) {
     const timestamp = new Date().toLocaleTimeString();
     const formattedMsg = `[${timestamp}] ERROR: ${msg} ${err ? (err.message || JSON.stringify(err)) : ''}`;
     console.error(formattedMsg);
     this.logSubscribers.forEach(cb => cb(formattedMsg));
  }

  public subscribe(ticker: string, callback: MarketCallback): () => void {
    const upperTicker = ticker.toUpperCase();

    if (!this.subscribers.has(upperTicker)) {
      this.subscribers.set(upperTicker, new Set());
    }
    this.subscribers.get(upperTicker)?.add(callback);

    if (this.currentTicker !== upperTicker) {
      this.currentTicker = upperTicker;
      this.log(`Switched to ${upperTicker}. Fetching real market data...`);
      this.startPolling();
    } else if (this.lastMarketData) {
       callback(this.lastMarketData);
    }

    return () => {
      const subs = this.subscribers.get(upperTicker);
      subs?.delete(callback);
      if (subs?.size === 0) {
        this.subscribers.delete(upperTicker);
        if (this.subscribers.size === 0) {
            this.stopPolling();
        }
      }
    };
  }

  private stopPolling() {
    if (this.pollingInterval) {
      clearInterval(this.pollingInterval);
      this.pollingInterval = null;
    }
    this.currentTicker = null;
  }

  private startPolling() {
    if (this.pollingInterval) clearInterval(this.pollingInterval);

    this.fetchFullMarketData();

    // Poll every 25 seconds to respect free tier limit (approx 5 calls/min)
    // We make 2 calls: Price + Chain
    this.pollingInterval = window.setInterval(() => {
      this.fetchFullMarketData();
    }, 25000); 
  }

  private async fetchFullMarketData() {
    if (!this.currentTicker) return;

    try {
      this.log(`Requesting price and chain for ${this.currentTicker}...`);

      // 1. Fetch Price (Previous Close for Free Tier)
      const priceUrl = `https://api.polygon.io/v2/aggs/ticker/${this.currentTicker}/prev?adjusted=true&apiKey=${API_KEY}`;
      const priceRes = await fetch(priceUrl);
      const priceData = await priceRes.json();

      if (priceData.status !== 'OK' || !priceData.results?.[0]) {
        throw new Error(priceData.error || 'Underlying price unavailable');
      }

      const currentPrice = priceData.results[0].c;
      this.log(`Price Received: $${currentPrice}`);

      // 2. Fetch Options Chain (Snapshot API)
      const chainUrl = `https://api.polygon.io/v3/snapshot/options/${this.currentTicker}?apiKey=${API_KEY}`;
      const chainRes = await fetch(chainUrl);
      const chainData = await chainRes.json();

      if (chainRes.status === 403) {
        throw new Error('Polygon Free Tier does not support Options Snapshots for this ticker. Try SPY/QQQ.');
      }

      if (chainData.status !== 'OK' || !chainData.results) {
        throw new Error(chainData.error || 'Options chain unavailable');
      }

      const rawResults = chainData.results;
      this.log(`Received ${rawResults.length} contracts for ${this.currentTicker}`);

      // Process raw snapshot results into our ExpirationDate format
      const chainMap: Record<string, OptionContract[]> = {};
      const today = new Date();

      rawResults.forEach((res: any) => {
        // We only want PUTS for CSP validation
        const details = res.details;
        if (!details || details.contract_type !== 'put') return;

        const expDate = details.expiration_date;
        if (!chainMap[expDate]) chainMap[expDate] = [];

        const greeks = res.greeks || {};
        const day = res.day || {};

        chainMap[expDate].push({
          strike: details.strike_price,
          bid: day.b || null,
          ask: day.a || null,
          last: day.c || null,
          vol: day.v || null,
          oi: res.open_interest || null,
          delta: greeks.delta || null,
          theta: greeks.theta || null
        });
      });

      const processedChain: ExpirationDate[] = Object.keys(chainMap).sort().map(dateStr => {
        const expDate = new Date(dateStr);
        const dte = Math.ceil((expDate.getTime() - today.getTime()) / (1000 * 60 * 60 * 24));
        return {
          date: dateStr,
          daysToExpiration: dte,
          strikes: chainMap[dateStr].sort((a, b) => a.strike - b.strike)
        };
      });

      const data: MarketData = {
        ticker: this.currentTicker,
        currentPrice,
        lastUpdated: Date.now(),
        chain: processedChain
      };

      this.lastMarketData = data;
      const subs = this.subscribers.get(this.currentTicker.toUpperCase());
      if (subs) {
        subs.forEach(callback => callback(data));
      }

    } catch (e: any) {
      this.error(`Market data sync failed.`, e);
      // Ensure subscribers know the sync failed by not calling them with bad data
      // but log it to the console so UI doesn't hang without info.
    }
  }
}

export const marketService = new MarketDataService();

