export const DEFAULT_TARGET_APY = 15;
export const DEFAULT_TARGET_DISCOUNT = 5;

export const SUPPORTED_TICKERS = ["SPY", "QQQ", "IWM", "TSLA", "AAPL", "AMD", "NVDA", "RIVN"];

import { MarketData, ExpirationDate, OptionContract } from '../types';
import { API_KEY, WS_API_BASE_URL } from '../constants';

type MarketCallback = (data: MarketData) => void;
type LogCallback = (message: string) => void;

export class MarketDataService {
  private subscribers: Map<string, Set<MarketCallback>> = new Map();
  private logSubscribers: Set<LogCallback> = new Set();
  private currentTicker: string | null = null;
  private socket: WebSocket | null = null;
  private lastMarketData: MarketData | null = null;
  private isSocketAuthenticated = false;

  constructor() {}

  public subscribeLogs(callback: LogCallback): () => void {
    this.logSubscribers.add(callback);
    return () => this.logSubscribers.delete(callback);
  }

  private log(msg: string) {
    const timestamp = new Date().toLocaleTimeString();
    this.logSubscribers.forEach(cb => cb(`[${timestamp}] ${msg}`));
  }

  private error(msg: string, err?: any) {
    const timestamp = new Date().toLocaleTimeString();
    this.logSubscribers.forEach(cb => cb(`[${timestamp}] ERROR: ${msg} ${err?.message || ''}`));
  }

  public subscribe(ticker: string, callback: MarketCallback): () => void {
    const upperTicker = ticker.toUpperCase();
    if (!this.subscribers.has(upperTicker)) {
      this.subscribers.set(upperTicker, new Set());
    }
    this.subscribers.get(upperTicker)?.add(callback);

    if (this.currentTicker !== upperTicker) {
      this.currentTicker = upperTicker;
      this.initRealTimeConnection();
      this.fetchMetadata(); // Still fetch chain via REST
    } else if (this.lastMarketData) {
       callback(this.lastMarketData);
    }

    return () => {
      const subs = this.subscribers.get(upperTicker);
      subs?.delete(callback);
      if (subs?.size === 0) {
        this.subscribers.delete(upperTicker);
        if (this.subscribers.size === 0) this.closeSocket();
      }
    };
  }

  private initRealTimeConnection() {
    this.closeSocket();
    this.log(`Initiating WebSocket for ${this.currentTicker}...`);

    this.socket = new WebSocket(WS_API_BASE_URL);

    this.socket.onopen = () => {
      this.log("WebSocket Connection Opened.");
      this.socket?.send(JSON.stringify({ action: "auth", params: API_KEY }));
    };

    this.socket.onmessage = (event) => {
      const messages = JSON.parse(event.data);
      messages.forEach((msg: any) => {
        if (msg.ev === "status") {
          this.log(`Socket Status: ${msg.message}`);
          if (msg.status === "auth_success") {
            this.isSocketAuthenticated = true;
            this.subscribeToTicker();
          }
        } else if (msg.ev === "A" || msg.ev === "AM") {
          // Aggregate minute or per-second
          if (msg.sym === this.currentTicker) {
            this.updatePrice(msg.c);
          }
        }
      });
    };

    this.socket.onerror = (err) => this.error("WebSocket Error", err);
    this.socket.onclose = () => {
      this.log("WebSocket Connection Closed.");
      this.isSocketAuthenticated = false;
    };
  }

  private subscribeToTicker() {
    if (this.socket && this.isSocketAuthenticated && this.currentTicker) {
      this.log(`Streaming live ticks for ${this.currentTicker}`);
      // Subscribe to Second aggregates (A) for higher frequency
      this.socket.send(JSON.stringify({ action: "subscribe", params: `A.${this.currentTicker}` }));
    }
  }

  private updatePrice(newPrice: number) {
    if (this.lastMarketData) {
      this.lastMarketData = {
        ...this.lastMarketData,
        currentPrice: newPrice,
        lastUpdated: Date.now()
      };
      this.subscribers.get(this.currentTicker!)?.forEach(cb => cb(this.lastMarketData!));
    }
  }

  private closeSocket() {
    if (this.socket) {
      this.socket.close();
      this.socket = null;
    }
  }

  private async fetchMetadata() {
    if (!this.currentTicker) return;
    try {
      this.log(`Fetching chain metadata for ${this.currentTicker}...`);

      const priceUrl = `https://api.polygon.io/v2/aggs/ticker/${this.currentTicker}/prev?adjusted=true&apiKey=${API_KEY}`;
      const priceRes = await fetch(priceUrl);
      const priceData = await priceRes.json();
      const currentPrice = priceData.results?.[0]?.c || 0;

      const contractsUrl = `https://api.polygon.io/v3/reference/options/contracts?underlying_ticker=${this.currentTicker}&contract_type=put&expired=false&limit=1000&apiKey=${API_KEY}`;
      const contractsRes = await fetch(contractsUrl);
      const contractsData = await contractsRes.json();

      if (!contractsData.results) throw new Error("No option contracts found.");

      const today = new Date();
      const expMap: Record<string, number> = {};

      contractsData.results.forEach((c: any) => {
        const exp = c.expiration_date;
        if (!expMap[exp]) {
           const dte = Math.ceil((new Date(exp).getTime() - today.getTime()) / (1000 * 60 * 60 * 24));
           if (dte >= 0) expMap[exp] = dte;
        }
      });

      const chain: ExpirationDate[] = Object.entries(expMap)
        .sort(([a], [b]) => a.localeCompare(b))
        .map(([date, dte]) => ({
          date,
          daysToExpiration: dte,
          strikes: [] 
        }));

      contractsData.results.forEach((c: any) => {
        const dateObj = chain.find(e => e.date === c.expiration_date);
        if (dateObj) {
          dateObj.strikes.push({
            strike: c.strike_price,
            ticker: c.ticker,
            bid: null, ask: null, last: null, vol: null, oi: null, delta: null, theta: null
          } as any);
        }
      });

      this.lastMarketData = {
        ticker: this.currentTicker,
        currentPrice: this.lastMarketData?.currentPrice || currentPrice,
        lastUpdated: Date.now(),
        chain
      };

      this.subscribers.get(this.currentTicker)?.forEach(cb => cb(this.lastMarketData!));
      this.log(`Chain mapped. Awaiting live price stream.`);

    } catch (e: any) {
      this.error(`Metadata sync failed`, e);
    }
  }

  public async fetchContractQuote(optionTicker: string): Promise<Partial<OptionContract>> {
    try {
      const nbboUrl = `https://api.polygon.io/v2/last/nbbo/${optionTicker}?apiKey=${API_KEY}`;
      const nbboRes = await fetch(nbboUrl);
      const nbboData = await nbboRes.json();

      let bid = nbboData.results?.p || 0;
      let ask = nbboData.results?.P || 0;

      if (bid === 0) {
        const prevUrl = `https://api.polygon.io/v2/aggs/ticker/${optionTicker}/prev?adjusted=true&apiKey=${API_KEY}`;
        const prevRes = await fetch(prevUrl);
        const prevData = await prevRes.json();

        if (prevData.results?.[0]) {
          const lastClose = prevData.results[0].c;
          return { bid: lastClose, ask: lastClose, last: lastClose };
        }
      }

      return { bid, ask, last: bid };
    } catch (e) {
      this.error(`Quote fetch failed for ${optionTicker}`, e);
      return {};
    }
  }
}

export const marketService = new MarketDataService();

import { GoogleGenAI } from "@google/genai";
import { TradeCalculation, TradeInputs } from '../types';

export const analyzeTradeRisk = async (
  inputs: TradeInputs,
  calculation: TradeCalculation,
  currentPrice: number
): Promise<string> => {
  if (!process.env.API_KEY) {
    return "Gemini API Key not configured. Unable to fetch analysis.";
  }

  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const prompt = `
    You are a senior financial risk analyst. Provide a concise risk assessment (max 100 words) for the following Cash-Secured Put (CSP) trade.

    Ticker: ${inputs.ticker}
    Current Price: $${currentPrice.toFixed(2)}

    Trade Details:
    - Strike Price: $${calculation.calculatedStrike}
    - Expiration (DTE): ${calculation.dte} days
    - Target Discount: ${inputs.targetDiscount}%
    - Collateral: $${calculation.collateral}
    - Premium Received: $${calculation.actualTotalCredit}
    - Annualized Return (APY): ${calculation.actualAPY.toFixed(2)}%

    Target APY was ${inputs.targetAPY}%. ${calculation.isTargetMet ? "Target Met." : "Target Missed."}

    Assess the downside risk, the quality of the premium relative to the risk, and the buffer against a drop. Be direct and professional.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });
    return response.text || "No analysis generated.";
  } catch (error) {
    console.error("Gemini Analysis Error:", error);
    return "Unable to generate analysis at this time.";
  }
};

import React, { useEffect, useState, useMemo, useRef } from 'react';
import { MarketData, TradeInputs, TradeCalculation, OptionContract } from './types';
import { DEFAULT_TARGET_APY, DEFAULT_TARGET_DISCOUNT, DEFAULT_TICKER } from './constants';
import { marketService } from './services/marketDataService';
import { InputPanel } from './components/InputPanel';
import { ResultsDisplay } from './components/ResultsDisplay';
import { ExpirationSelector } from './components/ExpirationSelector';
import { GeminiInsight } from './components/GeminiInsight';

const App: React.FC = () => {
  const [marketData, setMarketData] = useState<MarketData | null>(null);
  const [logs, setLogs] = useState<string[]>([]);
  const [showLogs, setShowLogs] = useState(false);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [fetchingQuote, setFetchingQuote] = useState(false);
  const [activeQuote, setActiveQuote] = useState<Partial<OptionContract> | null>(null);
  const [lastTickTime, setLastTickTime] = useState(0);

  const [inputs, setInputs] = useState<TradeInputs>({
    ticker: DEFAULT_TICKER,
    targetAPY: DEFAULT_TARGET_APY,
    targetDiscount: DEFAULT_TARGET_DISCOUNT,
    selectedDate: null,
  });

  const logsEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const unsubscribeLogs = marketService.subscribeLogs((msg) => {
      setLogs(prev => [...prev.slice(-99), msg]);
      if (msg.includes('ERROR')) {
        setErrorMsg(msg.split('ERROR: ')[1] || 'Sync Error');
      }
    });
    return () => unsubscribeLogs();
  }, []);

  useEffect(() => {
    if (showLogs && logsEndRef.current) {
      logsEndRef.current.scrollIntoView({ behavior: 'smooth' });
    }
  }, [logs, showLogs]);

  useEffect(() => {
    setInputs(prev => ({ ...prev, selectedDate: null }));
    setMarketData(null); 
    setErrorMsg(null);
    setActiveQuote(null);

    const unsubscribe = marketService.subscribe(inputs.ticker, (data) => {
      setMarketData(data);
      setLastTickTime(Date.now());
      setErrorMsg(null);
    });

    return () => unsubscribe();
  }, [inputs.ticker]);

  useEffect(() => {
    let isMounted = true;
    const updateQuote = async () => {
      if (!marketData || !inputs.selectedDate) return;

      const currentPrice = marketData.currentPrice;
      const targetStrike = currentPrice * (1 - inputs.targetDiscount / 100);
      const expirationData = marketData.chain.find(exp => exp.date === inputs.selectedDate);

      if (!expirationData || expirationData.strikes.length === 0) return;

      const closest = expirationData.strikes.reduce((prev, curr) => {
        return (Math.abs(curr.strike - targetStrike) < Math.abs(prev.strike - targetStrike) ? curr : prev);
      });

      const optTicker = (closest as any).ticker;
      if (optTicker) {
        setFetchingQuote(true);
        const quote = await marketService.fetchContractQuote(optTicker);
        if (isMounted) {
          setActiveQuote(quote);
          setFetchingQuote(false);
        }
      }
    };

    updateQuote();
    return () => { isMounted = false; };
  }, [marketData, inputs.selectedDate, inputs.targetDiscount]);

  const calculation: TradeCalculation | null = useMemo(() => {
    if (!marketData || !inputs.selectedDate) return null;

    const currentPrice = marketData.currentPrice;
    const targetStrike = currentPrice * (1 - inputs.targetDiscount / 100);
    const expirationData = marketData.chain.find(exp => exp.date === inputs.selectedDate);

    if (!expirationData || expirationData.strikes.length === 0) return null;

    const closestOption = expirationData.strikes.reduce((prev, curr) => {
      return (Math.abs(curr.strike - targetStrike) < Math.abs(prev.strike - targetStrike) ? curr : prev);
    });

    const dte = expirationData.daysToExpiration;
    const strike = closestOption.strike;
    const collateral = strike * 100;
    const requiredTotalCredit = collateral * (inputs.targetAPY / 100) * (dte / 365);

    const mergedOption: OptionContract = {
      ...closestOption,
      bid: activeQuote?.bid ?? null,
      ask: activeQuote?.ask ?? null,
      last: activeQuote?.last ?? null
    };

    const actualPremiumPerShare = mergedOption.bid || mergedOption.last || 0; 
    const actualTotalCredit = actualPremiumPerShare * 100;
    const actualAPY = collateral > 0 ? (actualTotalCredit / collateral) * (365 / dte) * 100 : 0;
    const netPurchasePrice = strike - actualPremiumPerShare;

    return {
      calculatedStrike: strike,
      collateral,
      dte,
      requiredTotalCredit,
      actualTotalCredit,
      actualAPY,
      netPurchasePrice,
      isTargetMet: actualTotalCredit >= requiredTotalCredit && actualTotalCredit > 0,
      actualPremiumPerShare,
      option: mergedOption
    };
  }, [marketData, inputs.selectedDate, inputs.targetAPY, inputs.targetDiscount, activeQuote]);

  // Handle price update animation
  const [pulse, setPulse] = useState(false);
  useEffect(() => {
    if (lastTickTime > 0) {
      setPulse(true);
      const timer = setTimeout(() => setPulse(false), 300);
      return () => clearTimeout(timer);
    }
  }, [lastTickTime]);

  return (
    <div className="min-h-screen bg-slate-950 text-slate-200 pb-80 selection:bg-indigo-500/30">
      <header className="bg-slate-900 border-b border-slate-800 sticky top-0 z-50 backdrop-blur-xl bg-opacity-90">
        <div className="max-w-7xl mx-auto px-6 h-16 flex items-center justify-between">
          <div className="flex items-center space-x-3">
             <div className="w-10 h-10 bg-indigo-600 rounded-2xl flex items-center justify-center text-white font-black font-mono shadow-lg shadow-indigo-600/20">
               CV
             </div>
             <h1 className="text-lg font-black tracking-tighter text-white uppercase">
               CSP <span className="text-indigo-500">PRO</span>
             </h1>
          </div>

          <div className="flex items-center space-x-4">
            <div className={`flex items-center px-4 py-1.5 rounded-full text-[10px] font-black tracking-widest border transition-colors ${errorMsg ? 'bg-rose-950/20 text-rose-500 border-rose-900/50' : 'bg-indigo-950/20 text-indigo-400 border-indigo-900/50'}`}>
               <span className={`w-2 h-2 rounded-full mr-2 ${errorMsg ? 'bg-rose-500' : 'bg-emerald-400 animate-pulse'}`}></span>
               {errorMsg ? 'SYNC ERROR' : 'REAL-TIME STREAMING'}
            </div>

            <div className={`flex items-center space-x-4 bg-slate-950 rounded-2xl px-5 py-2 border transition-all duration-300 ${pulse ? 'border-indigo-500 shadow-lg shadow-indigo-500/10' : 'border-slate-800'}`}>
              <span className="font-mono font-black text-indigo-400 uppercase text-sm">{inputs.ticker}</span>
              <span className="h-4 w-px bg-slate-800"></span>
              <span className={`font-mono font-bold text-sm transition-all duration-200 ${!marketData ? 'animate-pulse text-slate-600' : (pulse ? 'text-indigo-400' : 'text-slate-100')}`}>
                {marketData ? `$${marketData.currentPrice.toFixed(2)}` : 'SCANNING...'}
              </span>
            </div>
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-6 py-12 space-y-10">
        <div className="max-w-3xl">
          <h2 className="text-4xl font-black text-white mb-4 tracking-tighter">Validate CSP Yield.</h2>
          <p className="text-slate-500 leading-relaxed text-lg">
            Connected to Polygon.io WebSocket clusters. Your trade math now adjusts instantly as the market moves.
          </p>
          {errorMsg && (
            <div className="mt-6 p-4 bg-rose-950/20 border border-rose-900/50 rounded-2xl flex items-center gap-4">
              <span className="text-rose-500 text-xl font-bold">!</span>
              <p className="text-rose-400 text-sm font-bold uppercase tracking-wide">{errorMsg}</p>
            </div>
          )}
        </div>

        <InputPanel inputs={inputs} setInputs={setInputs} />

        {marketData && (
          <div className="bg-slate-900/30 p-8 rounded-3xl border border-slate-800/40 backdrop-blur-sm">
             <ExpirationSelector 
               chain={marketData.chain} 
               selectedDate={inputs.selectedDate} 
               onSelect={(date) => setInputs(prev => ({ ...prev, selectedDate: date }))}
             />

             <div className={fetchingQuote ? 'opacity-40 grayscale blur-[1px] transition-all duration-300' : 'transition-all duration-300'}>
               <ResultsDisplay calculation={calculation} inputs={inputs} />
             </div>

             {calculation && marketData && !fetchingQuote && (
               <GeminiInsight 
                 inputs={inputs} 
                 calculation={calculation} 
                 currentPrice={marketData.currentPrice} 
               />
             )}
          </div>
        )}
      </main>

      <div className={`fixed bottom-0 left-0 right-0 bg-slate-950 border-t border-slate-800 transition-all duration-500 ease-in-out ${showLogs ? 'h-72' : 'h-12'}`}>
        <div 
          className="flex items-center justify-between px-6 h-12 bg-slate-900 cursor-pointer hover:bg-slate-850"
          onClick={() => setShowLogs(!showLogs)}
        >
           <h3 className="text-[10px] font-black text-slate-500 uppercase tracking-widest flex items-center gap-3">
             <span className={`w-2 h-2 rounded-full ${logs.some(l => l.includes('ERROR')) ? 'bg-rose-500' : 'bg-indigo-500 animate-pulse'}`}></span>
             WebSocket & API Traffic
           </h3>
           <span className="text-slate-600 text-[10px] font-black uppercase tracking-widest">{showLogs ? 'Hide Activity' : 'Show Activity'}</span>
        </div>

        {showLogs && (
          <div className="h-60 overflow-y-auto p-6 font-mono text-[11px] leading-relaxed text-slate-400 bg-slate-950/50">
            {logs.map((log, i) => (
              <div key={i} className={`mb-1 border-l-2 pl-3 py-0.5 ${log.includes('ERROR') ? 'border-rose-800 bg-rose-950/10 text-rose-300' : 'border-indigo-900/40'}`}>
                {log}
              </div>
            ))}
            <div ref={logsEndRef} />
          </div>
        )}
      </div>
    </div>
  );
};

export default App;

