          </div>

          <div className="flex items-center space-x-4">
            <div className={`flex items-center px-4 py-1.5 rounded-full text-[10px] font-black tracking-widest border transition-colors ${errorMsg ? 'bg-rose-950/20 text-rose-500 border-rose-900/50' : 'bg-emerald-950/20 text-emerald-400 border-emerald-900/50'}`}>
               <span className={`w-2 h-2 rounded-full mr-2 ${errorMsg ? 'bg-rose-500' : 'bg-emerald-400 animate-pulse'}`}></span>
               {errorMsg ? 'FEED ERROR' : 'DATABENTO HF FEED'}
            </div>

            <div className={`flex items-center space-x-4 bg-slate-950 rounded-2xl px-5 py-2 border transition-all duration-300 ${pulse ? 'border-indigo-500 shadow-lg shadow-indigo-500/10' : 'border-slate-800'}`}>
              <span className="font-mono font-black text-indigo-400 uppercase text-sm">{inputs.ticker}</span>
