          <p className="text-slate-500 leading-relaxed text-lg">
            Powered by Databento high-fidelity market data. Validating trade math against {isSim ? 'local OPRA simulation' : 'real-time OPRA data streams'}.
          </p>
          {errorMsg && (
            <div className="mt-6 p-4 bg-rose-950/20 border border-rose-900/50 rounded-2xl flex items-center gap-4">
